<script lang="ts">
 import {base} from '$app/paths';import SiteHeader from '$lib/SiteHeader.svelte';import {renderArticle,headings} from '$lib/article-renderer';import {articles} from '$lib/articles';
 let {data}=$props();let copyStatus=$state('复制模板');let templateOpen=$state(false);const toc=$derived(headings(data.article.body));const previous=$derived(articles.find(a=>a.order===data.article.order-1));const next=$derived(articles.find(a=>a.order===data.article.order+1));
 async function copy(){try{await navigator.clipboard.writeText(data.article.template);copyStatus='已复制';}catch{templateOpen=true;copyStatus='复制未成功，请选择下方模板复制';}}
</script>
<svelte:head><title>{data.article.title}｜Open Marketing 实践手册</title><meta name="description" content={data.article.deck}/></svelte:head>
<div class="page-shell"><SiteHeader/><main class="book-layout"><aside class="chapter-sidebar"><a href={`${base}/articles/`}>从需求到增长</a><span>实践手册 / 全书目录</span>{#each articles as a}<a class:current={a.slug===data.article.slug} aria-current={a.slug===data.article.slug?'page':undefined} href={`${base}/articles/${a.slug}/`}>0{a.order}<strong>{a.title}</strong></a>{/each}</aside><article class="chapter-content"><details class="mobile-chapters"><summary>全书目录 · 第 {data.article.order} 章</summary>{#each articles as a}<a href={`${base}/articles/${a.slug}/`}>0{a.order} · {a.title}</a>{/each}</details><header class="chapter-title"><span class="card-kicker">CHAPTER 0{data.article.order} / {data.article.topic}</span><h1>{data.article.title}</h1><p>{data.article.deck}</p><div class="chapter-outcome">本章成果 <strong>{data.article.outcome}</strong></div></header><details class="chapter-toc"><summary>本章目录</summary>{#each toc as h}<a href={`#${h.id}`}>{h.text}</a>{/each}<a href="#worksheet">填写工作模板</a></details><div class="article-body">{@html renderArticle(data.article.body,base)}</div><section class="worksheet" id="worksheet"><span class="card-kicker">YOUR NEXT STEP</span><h2>{data.article.outcome}</h2><p>复制或下载后，为你的项目填写。无法确认的部分标注“待验证”。</p><div class="worksheet-actions"><button onclick={copy}>{copyStatus}</button><a href={`${base}/templates/${data.article.slug}.md`} download>下载 Markdown ↓</a></div><p class="sr-only" aria-live="polite">{copyStatus}</p><details class="worksheet-preview" bind:open={templateOpen}><summary>展开查看完整模板</summary><pre>{data.article.template}</pre></details></section>{#if data.article.tools.length}<section class="chapter-tools"><h2>需要工具时</h2>{#each data.article.tools as tool}<a href={`${base}/skills/${tool.id}/`}>{tool.title} ↗</a>{/each}</section>{/if}<aside class="source-note"><p>{data.article.sourceNote}</p></aside><nav class="chapter-pagination" aria-label="章节翻页">{#if previous}<a href={`${base}/articles/${previous.slug}/`}><small>← 上一章</small>{previous.title}</a>{:else}<a href={`${base}/articles/`}><small>← 阅读指南</small>查看全书目录</a>{/if}{#if next}<a href={`${base}/articles/${next.slug}/`}><small>下一章 →</small>{next.title}</a>{:else}<a href={`${base}/tools/`}><small>开始实践 →</small>按任务找开源工具</a>{/if}</nav></article></main></div>
